        private static void OpenProjection(Window owner, DeepSystemsContext ctx, WorldIndex index, string sourceKind, string sourceId, string fingerprint, Func<OperationsResearchModel> factory)
        {
            Load(ctx); List<OperationsResearchModel> existing = Store.Models.Where(x => Eq(x.SourceKind, sourceKind) && Eq(x.SourceId, sourceId)).OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).ToList(); OperationsResearchModel exact = existing.FirstOrDefault(x => Eq(x.SourceFingerprint, fingerprint)); if (exact != null) { OpenModel(owner, ctx, index, exact); return; } if (existing.Count > 0) { MessageBoxResult drift = MessageBox.Show(owner, "The source fingerprint has changed since the latest operations projection.\n\nYES · create a traceable child revision\nNO · open the historical projection\nCANCEL · leave unchanged", "YOMI · SOURCE DRIFT BOUNDARY", MessageBoxButton.YesNoCancel, MessageBoxImage.Warning); if (drift == MessageBoxResult.No) { OpenModel(owner, ctx, index, existing[0]); return; } if (drift != MessageBoxResult.Yes) return; }
            OperationsResearchModel model = factory == null ? StarterModel("Untitled operations model", "Declared optimization system.") : factory(); if (model == null) return; EnsureOperationalSeed(model); model.Id = Id("operations-model"); model.ParentModelId = existing.Count == 0 ? null : existing[0].Id; model.SourceKind = sourceKind; model.SourceId = sourceId; model.SourceFingerprint = fingerprint; model.CreatedUtc = Now(); model.UpdatedUtc = model.CreatedUtc; model.Revision = existing.Count == 0 ? 1 : Math.Max(1, existing[0].Revision) + 1; Store.Models.Insert(0, model); Save(ctx); AppendLedger(ctx, "MODEL_PROJECTED", model.Id, sourceKind + ":" + sourceId + (existing.Count == 0 ? "" : " · source drift child of " + existing[0].Id), OperationsResearchKernel.Fingerprint(model), ""); OpenModel(owner, ctx, index, model);
        }

