        private static void OpenRegistry(Window owner, DeepSystemsContext ctx, WorldIndex index) { Load(ctx); Window w = W(owner, "YOMI · OPERATIONS MODEL REGISTRY", 1240, 820); DockPanel root = Shell("OPERATIONS MODEL REGISTRY", CensusLine()); WrapPanel tools = new WrapPanel(); tools.Children.Add(Btn("CREATE MODEL", delegate { CreateModel(w, ctx, index); })); tools.Children.Add(Btn("SOLVE VAULT", delegate { OpenArtifactVault(w, ctx); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); ListBox list = List(); list.ItemsSource = Store.Models.OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).ToList(); list.MouseDoubleClick += delegate { OperationsResearchModel m = list.SelectedItem as OperationsResearchModel; if (m != null) OpenModel(w, ctx, index, m); }; root.Children.Add(list); w.Content = root; w.Show(); }

        private static void OpenModel(Window owner, DeepSystemsContext ctx, WorldIndex index, OperationsResearchModel model)
        {
            Window w = W(owner, "YOMI · OPERATIONS MODEL · " + (model.Name ?? model.Id), 1360, 900); DockPanel root = Shell((model.Status ?? "ACTIVE") + " · " + (model.Name ?? "OPERATIONS MODEL"), (model.Description ?? "") + "\r\nFingerprint " + Short(OperationsResearchKernel.Fingerprint(model), 24) + " · source " + (model.SourceKind ?? "MANUAL") + ":" + (model.SourceId ?? "∅") + " · budget " + model.Budget.ToString("0.###", CultureInfo.InvariantCulture)); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) };
            tools.Children.Add(Btn("SOLVE ALL", delegate { RunBundle(w, ctx, model); })); tools.Children.Add(Btn("ROUTES", delegate { OpenRouting(w, model); })); tools.Children.Add(Btn("SCHEDULE", delegate { OpenSchedule(w, model); })); tools.Children.Add(Btn("ASSIGNMENT", delegate { OpenAssignment(w, model); })); tools.Children.Add(Btn("FLOW", delegate { OpenFlow(w, model); })); tools.Children.Add(Btn("FACILITIES", delegate { OpenFacilities(w, model); })); tools.Children.Add(Btn("SLOTTING", delegate { OpenSlotting(w, model); })); tools.Children.Add(Btn("STAFFING", delegate { OpenStaffing(w, model); })); tools.Children.Add(Btn("INVENTORY", delegate { OpenInventory(w, model); })); tools.Children.Add(Btn("PORTFOLIO", delegate { OpenPortfolio(w, model); })); tools.Children.Add(Btn("STRESS", delegate { RunStress(w, ctx, model); })); tools.Children.Add(Btn("TRADE SPACE", delegate { RunTradeSpace(w, ctx, model); })); tools.Children.Add(Btn("SENSITIVITY", delegate { OpenSensitivity(w, model); })); tools.Children.Add(Btn("CONFIGURE", delegate { ConfigureModel(w, ctx, model); })); tools.Children.Add(Btn("ADD LOCATION", delegate { AddLocation(w, ctx, model); })); tools.Children.Add(Btn("ADD ARC", delegate { AddArc(w, ctx, model); })); tools.Children.Add(Btn("ADD SHIPMENT", delegate { AddShipment(w, ctx, model); })); tools.Children.Add(Btn("ADD VEHICLE", delegate { AddVehicle(w, ctx, model); })); tools.Children.Add(Btn("ADD TASK", delegate { AddTask(w, ctx, model); })); tools.Children.Add(Btn("ADD RESOURCE", delegate { AddResource(w, ctx, model); })); tools.Children.Add(Btn("ADD WORKER", delegate { AddWorker(w, ctx, model); })); tools.Children.Add(Btn("ADD SHIFT", delegate { AddShift(w, ctx, model); })); tools.Children.Add(Btn("ADD FACILITY", delegate { AddFacility(w, ctx, model); })); tools.Children.Add(Btn("ADD INVENTORY", delegate { AddInventory(w, ctx, model); })); tools.Children.Add(Btn("ADD SLOT", delegate { AddSlot(w, ctx, model); })); tools.Children.Add(Btn("ADD OPTION", delegate { AddPortfolio(w, ctx, model); })); tools.Children.Add(Btn("ADD SCENARIO", delegate { AddScenario(w, ctx, model); })); tools.Children.Add(Btn("PREREGISTER", delegate { CreateCapsule(w, ctx, model); })); tools.Children.Add(Btn("FREEZE BASELINE", delegate { FreezeBaseline(w, ctx, model); })); tools.Children.Add(Btn("DOSSIER", delegate { CreateDossier(w, ctx, model); })); tools.Children.Add(Btn("FORK", delegate { ForkModel(w, ctx, index, model); })); tools.Children.Add(Btn(Active(model.Status) ? "ARCHIVE" : "RESTORE", delegate { model.Status = Active(model.Status) ? "ARCHIVED" : "ACTIVE"; Touch(model); Save(ctx); AppendLedger(ctx, "MODEL_" + model.Status, model.Id, model.Name, OperationsResearchKernel.Fingerprint(model), ""); w.Close(); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, model.Name, model, StorePath(ctx), "$models:" + model.Id, "OPERATIONS RESEARCH › MODEL"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools);
            Grid body = new Grid(); for (int i = 0; i < 4; i++) body.ColumnDefinitions.Add(new ColumnDefinition()); ListBox network = List(), work = List(), assets = List(), artifacts = List(); network.ItemsSource = model.Locations.Cast<object>().Concat(model.Arcs.Cast<object>()).Concat(model.Shipments.Cast<object>()).ToList(); work.ItemsSource = model.Tasks.Cast<object>().Concat(model.Resources.Cast<object>()).Concat(model.ShiftRequirements.Cast<object>()).ToList(); assets.ItemsSource = model.Vehicles.Cast<object>().Concat(model.Workers.Cast<object>()).Concat(model.Facilities.Cast<object>()).Concat(model.Inventory.Cast<object>()).Concat(model.WarehouseSlots.Cast<object>()).Concat(model.Portfolio.Cast<object>()).Concat(model.Scenarios.Cast<object>()).ToList(); artifacts.ItemsSource = Store.Solves.Where(x => Eq(x.ModelId, model.Id)).Cast<object>().Concat(Store.StressRuns.Where(x => Eq(x.ModelId, model.Id)).Cast<object>()).Concat(Store.TradeSpaces.Where(x => Eq(x.ModelId, model.Id)).Cast<object>()).Concat(Store.Baselines.Where(x => Eq(x.ModelId, model.Id)).Cast<object>()).Concat(Store.Capsules.Where(x => Eq(x.ModelId, model.Id)).Cast<object>()).ToList(); Grid.SetColumn(network, 0); Grid.SetColumn(work, 1); Grid.SetColumn(assets, 2); Grid.SetColumn(artifacts, 3); body.Children.Add(network); body.Children.Add(work); body.Children.Add(assets); body.Children.Add(artifacts); root.Children.Add(body); w.Content = root; w.Show();
        }

        private static void CreateModel(Window owner, DeepSystemsContext ctx, WorldIndex index) { string name = Prompt(owner, "OPERATIONS MODEL FORGE", "Model name", "Integrated logistics and resource world"); if (String.IsNullOrWhiteSpace(name)) return; string description = PromptLarge(owner, "MODEL CHARTER", "Planning scope, objective and boundary", "Optimize declared routes, schedules, resources, facilities, staffing, inventory and portfolio decisions under explicit constraints."); if (description == null) return; OperationsResearchModel m = StarterModel(name.Trim(), description.Trim()); m.Id = Id("operations-model"); m.CreatedUtc = Now(); m.UpdatedUtc = m.CreatedUtc; Store.Models.Insert(0, m); Save(ctx); AppendLedger(ctx, "MODEL_CREATED", m.Id, m.Name, OperationsResearchKernel.Fingerprint(m), ""); OpenModel(owner, ctx, index, m); }
        private static OperationsResearchModel ProjectionModel(string name, string description) { OperationsResearchModel m = new OperationsResearchModel { Name = name, Description = description, Status = "ACTIVE", ObjectiveSense = "MINIMIZE_COST", Budget = 1000, FacilityLimit = 2, Seed = 1337 }; SeedParameters(m); m.Assumptions.Add("Every quantity, cost, duration, capacity and objective weight remains a declared planning input until independently evidenced."); return m; }
        private static OperationsResearchModel StarterModel(string name, string description) { OperationsResearchModel m = ProjectionModel(name, description); m.Locations.Add(new OrLocation { Id = "depot", Name = "Central depot", Kind = "DEPOT", X = 0, Y = 0, NetSupply = 100 }); m.Locations.Add(new OrLocation { Id = "north", Name = "North demand", Kind = "CUSTOMER", X = 4, Y = 8, NetSupply = -40 }); m.Locations.Add(new OrLocation { Id = "east", Name = "East demand", Kind = "CUSTOMER", X = 10, Y = 2, NetSupply = -35 }); m.Locations.Add(new OrLocation { Id = "south", Name = "South demand", Kind = "CUSTOMER", X = -3, Y = -7, NetSupply = -25 }); AddStarterArc(m, "a-depot-north", "depot", "north", 9, 9, 9, 70); AddStarterArc(m, "a-depot-east", "depot", "east", 10, 10, 10, 70); AddStarterArc(m, "a-depot-south", "depot", "south", 8, 8, 8, 50); AddStarterArc(m, "a-north-east", "north", "east", 9, 9, 8, 40); AddStarterArc(m, "a-east-south", "east", "south", 15, 15, 12, 40); AddStarterArc(m, "a-south-north", "south", "north", 16, 16, 13, 40); m.Shipments.Add(new OrShipment { Id = "delivery-north", Name = "North replenishment", OriginLocationId = "depot", DestinationLocationId = "north", Quantity = 40, ReadyTime = 0, DueTime = 40, ServiceTime = 2, Priority = 2, LatePenalty = 5 }); m.Shipments.Add(new OrShipment { Id = "delivery-east", Name = "East replenishment", OriginLocationId = "depot", DestinationLocationId = "east", Quantity = 35, ReadyTime = 0, DueTime = 35, ServiceTime = 2, Priority = 2, LatePenalty = 5 }); m.Shipments.Add(new OrShipment { Id = "delivery-south", Name = "South replenishment", OriginLocationId = "depot", DestinationLocationId = "south", Quantity = 25, ReadyTime = 5, DueTime = 45, ServiceTime = 2, Priority = 1, LatePenalty = 4 }); m.Vehicles.Add(new OrVehicle { Id = "vehicle-alpha", Name = "Vehicle Alpha", DepotLocationId = "depot", Capacity = 60, FixedCost = 20, CostPerDistance = 1, Speed = 1, AvailableUntil = 100, MaximumStops = 8 }); m.Vehicles.Add(new OrVehicle { Id = "vehicle-beta", Name = "Vehicle Beta", DepotLocationId = "depot", Capacity = 60, FixedCost = 20, CostPerDistance = 1, Speed = 1, AvailableUntil = 100, MaximumStops = 8 }); m.Tasks.Add(new OrTask { Id = "receive", Name = "Receive inbound stock", Duration = 4, DueTime = 10, ResourceKind = "WAREHOUSE", ResourceUnits = 1 }); m.Tasks.Add(new OrTask { Id = "pick", Name = "Pick outbound orders", Duration = 6, DueTime = 20, ResourceKind = "WAREHOUSE", ResourceUnits = 2, PredecessorIds = new List<string> { "receive" } }); m.Tasks.Add(new OrTask { Id = "load", Name = "Load fleet", Duration = 3, DueTime = 28, ResourceKind = "WAREHOUSE", ResourceUnits = 1, PredecessorIds = new List<string> { "pick" } }); m.Tasks.Add(new OrTask { Id = "dispatch", Name = "Dispatch routes", Duration = 1, DueTime = 30, ResourceKind = "DISPATCH", ResourceUnits = 1, PredecessorIds = new List<string> { "load" } }); m.Resources.Add(new OrResourcePool { Id = "warehouse-pool", Name = "Warehouse work cells", Kind = "WAREHOUSE", Capacity = 3, AvailableUntil = 100, UnitTimeCost = 2 }); m.Resources.Add(new OrResourcePool { Id = "dispatch-pool", Name = "Dispatch desk", Kind = "DISPATCH", Capacity = 1, AvailableUntil = 100, UnitTimeCost = 3 }); m.Workers.Add(new OrWorker { Id = "worker-a", Name = "Worker A", HomeLocationId = "depot", CostPerAssignment = 10, MaximumAssignments = 2, Skills = new List<string> { "WAREHOUSE", "GENERAL" }, EligibleShiftIds = new List<string> { "DAY" } }); m.Workers.Add(new OrWorker { Id = "worker-b", Name = "Worker B", HomeLocationId = "east", CostPerAssignment = 12, MaximumAssignments = 2, Skills = new List<string> { "WAREHOUSE", "DISPATCH", "GENERAL" }, EligibleShiftIds = new List<string> { "DAY", "EVENING" } }); m.Workers.Add(new OrWorker { Id = "worker-c", Name = "Worker C", HomeLocationId = "north", CostPerAssignment = 11, MaximumAssignments = 1, Skills = new List<string> { "DISPATCH", "GENERAL" }, EligibleShiftIds = new List<string> { "EVENING" } }); m.ShiftRequirements.Add(new OrShiftRequirement { Id = "day-warehouse", ShiftId = "DAY", Skill = "WAREHOUSE", RequiredWorkers = 2, UnderstaffPenalty = 500 }); m.ShiftRequirements.Add(new OrShiftRequirement { Id = "evening-dispatch", ShiftId = "EVENING", Skill = "DISPATCH", RequiredWorkers = 1, UnderstaffPenalty = 700 }); m.Facilities.Add(new OrFacilityCandidate { Id = "facility-depot", Name = "Central depot", LocationId = "depot", FixedCost = 100, Capacity = 100, Mandatory = true }); m.Facilities.Add(new OrFacilityCandidate { Id = "facility-east", Name = "East satellite", LocationId = "east", FixedCost = 70, Capacity = 60 }); m.Inventory.Add(new OrInventoryItem { Id = "sku-fast", Name = "Fast mover", Family = "GENERAL", RequiredZone = "A", AnnualDemand = 5000, DailyDemandMean = 20, DailyDemandStdDev = 5, OrderCost = 40, AnnualHoldingCost = 2, LeadTimeDays = 4, ServiceLevel = 0.97, ShortageCost = 10, PickFrequency = 5000, Cube = 1 }); m.Inventory.Add(new OrInventoryItem { Id = "sku-medium", Name = "Medium mover", Family = "GENERAL", RequiredZone = "B", AnnualDemand = 1800, DailyDemandMean = 7, DailyDemandStdDev = 2, OrderCost = 35, AnnualHoldingCost = 3, LeadTimeDays = 6, ServiceLevel = 0.95, ShortageCost = 8, PickFrequency = 1800, Cube = 1.5 }); m.Inventory.Add(new OrInventoryItem { Id = "sku-slow", Name = "Slow mover", Family = "GENERAL", RequiredZone = "C", AnnualDemand = 400, DailyDemandMean = 1.6, DailyDemandStdDev = 0.8, OrderCost = 30, AnnualHoldingCost = 4, LeadTimeDays = 8, ServiceLevel = 0.9, ShortageCost = 6, PickFrequency = 400, Cube = 2 }); m.WarehouseSlots.Add(new OrWarehouseSlot { Id = "slot-a", Name = "Forward pick A", Zone = "A", TravelDistance = 2, CubeCapacity = 1 }); m.WarehouseSlots.Add(new OrWarehouseSlot { Id = "slot-b", Name = "Mid pick B", Zone = "B", TravelDistance = 6, CubeCapacity = 1.5 }); m.WarehouseSlots.Add(new OrWarehouseSlot { Id = "slot-c", Name = "Reserve C", Zone = "C", TravelDistance = 12, CubeCapacity = 3 }); m.Portfolio.Add(new OrPortfolioItem { Id = "option-routing", Name = "Routing optimization program", Cost = 250, Value = 480, Risk = 40 }); m.Portfolio.Add(new OrPortfolioItem { Id = "option-slotting", Name = "Warehouse re-slotting", Cost = 180, Value = 310, Risk = 25 }); m.Portfolio.Add(new OrPortfolioItem { Id = "option-satellite", Name = "East satellite facility", Cost = 600, Value = 850, Risk = 120, ExclusiveGroup = "FACILITY_STRATEGY" }); m.Portfolio.Add(new OrPortfolioItem { Id = "option-outsourcing", Name = "Outsource overflow", Cost = 350, Value = 500, Risk = 90, ExclusiveGroup = "FACILITY_STRATEGY" }); m.Scenarios.Add(new OrScenario { Id = "base", Name = "Declared baseline" }); m.Scenarios.Add(new OrScenario { Id = "demand-surge", Name = "Demand surge", DemandMultiplier = 1.35, CapacityMultiplier = 1, TravelCostMultiplier = 1.05, DurationMultiplier = 1.1, ProbabilityWeight = 1 }); m.Scenarios.Add(new OrScenario { Id = "capacity-disruption", Name = "Capacity disruption", DemandMultiplier = 1.05, CapacityMultiplier = 0.65, TravelCostMultiplier = 1.2, DurationMultiplier = 1.25, ProbabilityWeight = 1 }); return m; }
        private static void SeedParameters(OperationsResearchModel m) { m.Parameters["demand_multiplier"] = 1; m.Parameters["travel_cost_multiplier"] = 1; m.Parameters["capacity_multiplier"] = 1; m.Parameters["duration_multiplier"] = 1; m.Parameters["risk_weight"] = 1; m.Parameters["unserved_penalty"] = 10000; m.Parameters["unscheduled_penalty"] = 10000; m.Parameters["flow_deficit_penalty"] = 10000; }
        private static void AddStarterArc(OperationsResearchModel m, string id, string from, string to, double distance, double time, double cost, double capacity) { m.Arcs.Add(new OrArc { Id = id, FromLocationId = from, ToLocationId = to, Distance = distance, TravelTime = time, UnitCost = cost, Capacity = capacity, Bidirectional = true }); }
        private static void EnsureOperationalSeed(OperationsResearchModel m) { if (m.Parameters == null) m.Parameters = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); SeedParametersIfMissing(m); if (m.Locations.Count == 0) m.Locations.Add(new OrLocation { Id = "origin", Name = "Declared origin", Kind = "DEPOT", NetSupply = 1 }); if (m.Locations.Count == 1) m.Locations.Add(new OrLocation { Id = "destination", Name = "Declared destination", Kind = "DEMAND", X = 1, NetSupply = -1 }); if (m.Arcs.Count == 0 && m.Locations.Count >= 2) m.Arcs.Add(new OrArc { Id = "seed-arc", FromLocationId = m.Locations[0].Id, ToLocationId = m.Locations[1].Id, Distance = 1, TravelTime = 1, UnitCost = 1, Capacity = 1, Bidirectional = true }); if (m.Vehicles.Count == 0) m.Vehicles.Add(new OrVehicle { Id = "seed-vehicle", Name = "Declared vehicle", DepotLocationId = m.Locations[0].Id, Capacity = 1 }); if (m.Shipments.Count == 0) m.Shipments.Add(new OrShipment { Id = "seed-shipment", Name = "Declared demand", OriginLocationId = m.Locations[0].Id, DestinationLocationId = m.Locations[1].Id, Quantity = 1, DueTime = 100 }); if (m.Resources.Count == 0) m.Resources.Add(new OrResourcePool { Id = "general-resource", Name = "General capacity", Kind = "GENERAL", Capacity = 1 }); if (m.Tasks.Count == 0) m.Tasks.Add(new OrTask { Id = "seed-task", Name = "Declared work", Duration = 1, ResourceKind = "GENERAL" }); if (m.Facilities.Count == 0) m.Facilities.Add(new OrFacilityCandidate { Id = "seed-facility", Name = "Declared facility", LocationId = m.Locations[0].Id, Capacity = Double.MaxValue, Mandatory = true }); }
        private static void SeedParametersIfMissing(OperationsResearchModel m) { Dictionary<string, double> defaults = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); OperationsResearchModel seed = new OperationsResearchModel(); SeedParameters(seed); defaults = seed.Parameters; foreach (KeyValuePair<string, double> x in defaults) if (!m.Parameters.ContainsKey(x.Key)) m.Parameters[x.Key] = x.Value; }

        private static void RunBundle(Window owner, DeepSystemsContext ctx, OperationsResearchModel model) { OrSolveBundle result = OperationsResearchKernel.SolveAll(model); string created = Now(), certificate = HashText(OperationsResearchKernel.Fingerprint(model) + "|" + created + "|" + Json.Serialize(result)); OrSolveRecord record = new OrSolveRecord { Id = Id("operations-solve"), ModelId = model.Id, CreatedUtc = created, ModelFingerprint = OperationsResearchKernel.Fingerprint(model), CertificateHash = certificate, Label = "GRAND OPTIMIZATION BUNDLE", Result = result }; Store.Solves.Insert(0, record); Save(ctx); AppendLedger(ctx, "SOLVE_BUNDLE_CERTIFIED", record.Id, model.Name, record.ModelFingerprint, certificate); List<object> rows = new List<object> { record, result, result.Routing, result.Schedule, result.Assignment, result.Flow, result.Facilities, result.Slotting, result.Staffing, result.Inventory, result.Portfolio }; rows.AddRange(result.Audit.Cast<object>()); OpenRows(owner, "GRAND OPTIMIZATION BUNDLE", rows, "Certificate " + certificate + " · advisory mathematics only"); }
        private static void RunStress(Window owner, DeepSystemsContext ctx, OperationsResearchModel model) { OrRobustnessResult result = OperationsResearchKernel.StressScenarios(model); string created = Now(), certificate = HashText(OperationsResearchKernel.Fingerprint(model) + "|" + created + "|" + Json.Serialize(result)); OrStressRecord record = new OrStressRecord { Id = Id("operations-stress"), ModelId = model.Id, CreatedUtc = created, ModelFingerprint = OperationsResearchKernel.Fingerprint(model), CertificateHash = certificate, Result = result }; Store.StressRuns.Insert(0, record); Save(ctx); AppendLedger(ctx, "SCENARIO_STRESS_CERTIFIED", record.Id, model.Name, record.ModelFingerprint, certificate); OpenRows(owner, "SCENARIO STRESS PLANETARIUM", new object[] { record, result }.Concat(result.Scores.Cast<object>()).Concat(result.Audit.Cast<object>()).ToArray(), "Recourse envelope across declared stress worlds · certificate " + certificate); }
        private static void RunTradeSpace(Window owner, DeepSystemsContext ctx, OperationsResearchModel model) { OrTradeSpaceResult result = OperationsResearchKernel.ExploreFacilityTradeSpace(model); string created = Now(), certificate = HashText(OperationsResearchKernel.Fingerprint(model) + "|" + created + "|" + Json.Serialize(result)); OrTradeRecord record = new OrTradeRecord { Id = Id("operations-trade"), ModelId = model.Id, CreatedUtc = created, ModelFingerprint = OperationsResearchKernel.Fingerprint(model), CertificateHash = certificate, Result = result }; Store.TradeSpaces.Insert(0, record); Save(ctx); AppendLedger(ctx, "TRADE_SPACE_CERTIFIED", record.Id, model.Name, record.ModelFingerprint, certificate); OpenRows(owner, "TRADE-SPACE CARTOGRAPHY", new object[] { record, result }.Concat(result.Points.Cast<object>()).Concat(result.Audit.Cast<object>()).ToArray(), "Facility-count Pareto coordinates · certificate " + certificate); }
        private static void RunShortestPath(Window owner, OperationsResearchModel model) { OrLocation from = ChooseObject(owner, "PATH ORIGIN", "Select origin", model.Locations.Where(x => Active(x.Status)).Cast<object>().ToList()) as OrLocation; if (from == null) return; OrLocation to = ChooseObject(owner, "PATH DESTINATION", "Select destination", model.Locations.Where(x => Active(x.Status) && !Eq(x.Id, from.Id)).Cast<object>().ToList()) as OrLocation; if (to == null) return; object metric = ChooseObject(owner, "PATH METRIC", "Minimize one declared edge metric", new object[] { "DISTANCE", "TIME", "COST" }); if (metric == null) return; OrPathResult result = OperationsResearchKernel.ShortestPath(model, from.Id, to.Id, metric.ToString()); OpenRows(owner, "SHORTEST-PATH ORACLE", new object[] { result }.Concat(result.Audit.Cast<object>()).ToArray(), "Dijkstra path over nonnegative declared arc weights"); }
        private static void OpenRouting(Window owner, OperationsResearchModel model) { OrRoutingResult r = OperationsResearchKernel.SolveVehicleRouting(model); OpenRows(owner, "ROUTING COMMAND", new object[] { r }.Concat(r.Routes.Cast<object>()).Concat(r.Routes.SelectMany(x => x.Stops).Cast<object>()).Concat(r.UnservedShipmentIds.Select(x => (object)("UNSERVED · " + x))).Concat(r.Audit.Cast<object>()).ToArray(), "Deterministic insertion + bounded 2-opt · not a global optimality certificate"); }
        private static void OpenSchedule(Window owner, OperationsResearchModel model) { OrScheduleResult r = OperationsResearchKernel.SolveSchedule(model); OpenRows(owner, "SCHEDULING CITADEL", new object[] { r }.Concat(r.Tasks.Cast<object>()).Concat(r.UnscheduledTaskIds.Select(x => (object)("UNSCHEDULED · " + x))).Concat(r.Audit.Cast<object>()).ToArray(), "Precedence/resource-feasible serial schedule generation"); }
        private static void OpenAssignment(Window owner, OperationsResearchModel model) { OrAssignmentResult r = OperationsResearchKernel.SolveAssignment(model); OpenRows(owner, "ASSIGNMENT EXCHANGE", new object[] { r }.Concat(r.Assignments.Cast<object>()).Concat(r.UnfilledTaskIds.Select(x => (object)("UNFILLED · " + x))).Concat(r.Audit.Cast<object>()).ToArray(), "Exact Hungarian solution for the declared one-to-one matrix"); }
        private static void OpenFlow(Window owner, OperationsResearchModel model) { OrFlowResult r = OperationsResearchKernel.SolveMinCostFlow(model); OpenRows(owner, "FLOW NETWORK REFINERY", new object[] { r }.Concat(r.Flows.Cast<object>()).Concat(r.Audit.Cast<object>()).ToArray(), "Successive shortest augmenting paths over the declared residual network"); }
        private static void OpenFacilities(Window owner, OperationsResearchModel model) { OrFacilityResult r = OperationsResearchKernel.SolveFacilityLocation(model, model.FacilityLimit); OpenRows(owner, "FACILITY CONSTELLATION", new object[] { r }.Concat(r.OpenFacilityIds.Select(x => (object)("OPEN · " + x))).Concat(r.Assignments.Cast<object>()).Concat(r.Audit.Cast<object>()).ToArray(), "Capacity-aware greedy-add and local exchange"); }
        private static void OpenSlotting(Window owner, OperationsResearchModel model) { OrSlottingResult r = OperationsResearchKernel.SolveWarehouseSlotting(model); OpenRows(owner, "WAREHOUSE SLOTTING FOUNDRY", new object[] { r }.Concat(r.Assignments.Cast<object>()).Concat(r.UnslottedItemIds.Select(x => (object)("UNSLOTTED · " + x))).Concat(r.Audit.Cast<object>()).ToArray(), "Exact declared item-slot cost matrix with compatibility blockers"); }
        private static void OpenStaffing(Window owner, OperationsResearchModel model) { OrStaffingResult r = OperationsResearchKernel.SolveStaffing(model); OpenRows(owner, "WORKFORCE COVERAGE GRID", new object[] { r }.Concat(r.Assignments.Cast<object>()).Concat(r.RemainingDeficits.Select(x => (object)(x.Key + " · deficit " + x.Value))).Concat(r.Audit.Cast<object>()).ToArray(), "Skills, shift eligibility, assignment caps and explicit understaff penalties"); }
        private static void OpenInventory(Window owner, OperationsResearchModel model) { OrInventoryResult r = OperationsResearchKernel.SolveInventory(model); OpenRows(owner, "INVENTORY POLICY VAULT", new object[] { r }.Concat(r.Policies.Cast<object>()).Concat(r.Audit.Cast<object>()).ToArray(), "EOQ + normal safety stock + newsvendor policy under declared stationarity"); }
        private static void OpenPortfolio(Window owner, OperationsResearchModel model) { OrPortfolioResult r = OperationsResearchKernel.SolvePortfolio(model); OpenRows(owner, "PORTFOLIO ALLOCATION ENGINE", new object[] { r }.Concat(r.SelectedItemIds.Select(x => (object)("SELECTED · " + x))).Concat(r.Audit.Cast<object>()).ToArray(), "Scaled budget dynamic program with dependency and exclusivity repair"); }
        private static void OpenSensitivity(Window owner, OperationsResearchModel model) { OrSensitivityResult r = OperationsResearchKernel.AnalyzeSensitivity(model, 0.05); OpenRows(owner, "SENSITIVITY TENSOR", new object[] { r }.Concat(r.Effects.Cast<object>()).Concat(r.Audit.Cast<object>()).ToArray(), "Local ±5% elementary effects over the composite loss"); }
        private static void OpenArtifactVault(Window owner, DeepSystemsContext ctx) { Load(ctx); OpenRows(owner, "OPTIMIZATION ARTIFACT VAULT", Store.Solves.Cast<object>().Concat(Store.StressRuns.Cast<object>()).Concat(Store.TradeSpaces.Cast<object>()).ToArray(), "Fingerprint-bound solve bundles, stress worlds and Pareto trade spaces"); }

        private static void ConfigureModel(Window owner, DeepSystemsContext ctx, OperationsResearchModel model) { string name = Prompt(owner, "MODEL CONFIGURATION", "Model name", model.Name); if (String.IsNullOrWhiteSpace(name)) return; string description = PromptLarge(owner, "MODEL CHARTER", "Planning scope and authority boundary", model.Description); if (description == null) return; string budgetRaw = Prompt(owner, "BUDGET", "Nonnegative portfolio budget", model.Budget.ToString("R", CultureInfo.InvariantCulture)); if (budgetRaw == null) return; string facilityRaw = Prompt(owner, "FACILITY LIMIT", "Maximum open facilities", model.FacilityLimit.ToString(CultureInfo.InvariantCulture)); if (facilityRaw == null) return; string objective = Prompt(owner, "OBJECTIVE SENSE", "Objective label", model.ObjectiveSense ?? "MINIMIZE_COST"); if (objective == null) return; string prm = PromptLarge(owner, "PARAMETER MANIFOLD", "One key=value declaration per line", String.Join(Environment.NewLine, model.Parameters.OrderBy(x => x.Key).Select(x => x.Key + "=" + x.Value.ToString("R", CultureInfo.InvariantCulture)).ToArray())); if (prm == null) return; Dictionary<string, double> parsed = Pairs(prm); if (parsed.Count == 0) return; model.Name = Short(name.Trim(), 512); model.Description = Short(description.Trim(), MaxLongText); model.Budget = Math.Max(0, Number(budgetRaw, model.Budget)); model.FacilityLimit = Integer(facilityRaw, model.FacilityLimit, 0, Math.Max(0, model.Facilities.Count)); model.ObjectiveSense = Short(objective.Trim().ToUpperInvariant(), 80); model.Parameters = parsed; SeedParametersIfMissing(model); Touch(model); Save(ctx); string fingerprint = OperationsResearchKernel.Fingerprint(model); AppendLedger(ctx, "MODEL_RECONFIGURED", model.Id, model.ObjectiveSense + " · budget " + model.Budget.ToString("R", CultureInfo.InvariantCulture), fingerprint, ""); MessageBox.Show(owner, "Configuration committed.\n\nFingerprint " + fingerprint, "YOMI · OPERATIONS MODEL", MessageBoxButton.OK, MessageBoxImage.Information); }
