        private static void CreateCapsule(Window owner, DeepSystemsContext ctx, OperationsResearchModel model) { string title = Prompt(owner, "PREREGISTER OPTIMIZATION", "Capsule title", "Planning question · " + model.Name); if (String.IsNullOrWhiteSpace(title)) return; string question = PromptLarge(owner, "DECISION QUESTION", "Exact decision question to freeze before solving", "Which declared plan best satisfies the explicit objective and constraints while retaining feasibility across the named stress worlds?"); if (question == null) return; string constraints = PromptLarge(owner, "CONSTRAINT DECLARATION", "Frozen constraint and exclusion statement", "All model capacities, time windows, precedence relations, skill requirements, budget limits, facility limits, dependencies and compatibility zones are binding as declared."); if (constraints == null) return; OrOptimizationCapsule c = new OrOptimizationCapsule { Id = Id("operations-capsule"), ModelId = model.Id, Title = title.Trim(), DecisionQuestion = question.Trim(), ObjectiveDeclaration = model.ObjectiveSense + " · budget " + model.Budget.ToString("R", CultureInfo.InvariantCulture), ConstraintDeclaration = constraints.Trim(), FrozenUtc = Now(), ModelFingerprint = OperationsResearchKernel.Fingerprint(model), FrozenParameters = new Dictionary<string, double>(model.Parameters, StringComparer.OrdinalIgnoreCase), Assumptions = new List<string>(model.Assumptions), EvidenceNodeIds = new List<string>(model.EvidenceNodeIds) }; c.CertificateHash = HashText(Json.Serialize(c) + "|" + c.ModelFingerprint); Store.Capsules.Insert(0, c); Save(ctx); AppendLedger(ctx, "CAPSULE_PREREGISTERED", c.Id, c.Title, c.ModelFingerprint, c.CertificateHash); OpenRows(owner, "OPTIMIZATION CAPSULE", c, c.AuthorityBoundary); }
        private static void OpenCapsules(Window owner, DeepSystemsContext ctx) { Load(ctx); OpenRows(owner, "OPTIMIZATION CAPSULE VAULT", Store.Capsules.ToArray(), "Immutable question, objective, constraint, solver and acceptance declarations"); }
        private static void FreezeBaseline(Window owner, DeepSystemsContext ctx, OperationsResearchModel model) { string name = Prompt(owner, "FREEZE OPERATIONS BASELINE", "Immutable baseline name", model.Name + " · baseline " + Now()); if (String.IsNullOrWhiteSpace(name)) return; string reason = PromptLarge(owner, "BASELINE RATIONALE", "Why this exact planning world must remain recoverable", "Preserve a reproducible reference before changing demands, capacities, costs, resources, constraints or objective weights."); if (reason == null) return; string snapshot = Json.Serialize(model), fp = OperationsResearchKernel.Fingerprint(model); OrModelBaseline parent = Store.Baselines.FirstOrDefault(x => Eq(x.ModelId, model.Id)); OrModelBaseline b = new OrModelBaseline { Id = Id("operations-baseline"), ModelId = model.Id, ParentBaselineId = parent == null ? null : parent.Id, Name = name.Trim(), Reason = reason.Trim(), Status = "FROZEN", FrozenUtc = Now(), ModelFingerprint = fp, SnapshotJson = snapshot }; b.BaselineFingerprint = BaselineFingerprint(b); Store.Baselines.Insert(0, b); Save(ctx); AppendLedger(ctx, "BASELINE_FROZEN", b.Id, b.Name, fp, b.BaselineFingerprint); OpenRows(owner, "IMMUTABLE OPERATIONS BASELINE", b, "Recomputed " + BaselineFingerprint(b)); }
        private static string BaselineFingerprint(OrModelBaseline b) { return HashText((b.Id ?? "") + "|" + (b.ModelId ?? "") + "|" + (b.ParentBaselineId ?? "") + "|" + (b.Name ?? "") + "|" + (b.FrozenUtc ?? "") + "|" + (b.Reason ?? "") + "|" + (b.ModelFingerprint ?? "") + "|" + (b.SnapshotJson ?? "")); }
        private static void OpenBaselines(Window owner, DeepSystemsContext ctx) { Load(ctx); OpenRows(owner, "IMMUTABLE OPERATIONS BASELINES", Store.Baselines.Cast<object>().Concat(Store.Baselines.Select(x => (object)(x.Id + "   ·   " + (Eq(x.BaselineFingerprint, BaselineFingerprint(x)) ? "VERIFIED" : "FINGERPRINT MISMATCH"))).ToArray()).ToArray(), "Full planning snapshots with lineage and recomputable SHA-256 identities"); }
        private static void CreateDossier(Window owner, DeepSystemsContext ctx, OperationsResearchModel model) { string title = Prompt(owner, "CREATE DECISION DOSSIER", "Dossier title", "Bounded operations recommendation · " + model.Name); if (String.IsNullOrWhiteSpace(title)) return; string recommendation = PromptLarge(owner, "BOUNDED RECOMMENDATION", "State only what the declared model and artifacts support", "Under the declared data, constraints, objective weights and approximation boundaries, the attached plan is a feasible advisory candidate for human review."); if (recommendation == null) return; string fp = OperationsResearchKernel.Fingerprint(model); OrSolveRecord solve = Store.Solves.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, fp)); OrStressRecord stress = Store.StressRuns.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, fp)); OrTradeRecord trade = Store.TradeSpaces.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, fp)); OrModelBaseline baseline = Store.Baselines.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, fp)); OrOptimizationCapsule capsule = Store.Capsules.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, fp)); OrDecisionDossier d = new OrDecisionDossier { Id = Id("operations-dossier"), ModelId = model.Id, SolveId = solve == null ? null : solve.Id, StressId = stress == null ? null : stress.Id, TradeId = trade == null ? null : trade.Id, BaselineId = baseline == null ? null : baseline.Id, CapsuleId = capsule == null ? null : capsule.Id, Title = title.Trim(), CreatedUtc = Now(), UpdatedUtc = Now(), ModelFingerprint = fp, BoundedRecommendation = recommendation.Trim(), EvidenceNodeIds = new List<string>(model.EvidenceNodeIds) }; d.FeasibilityConditions.Add("All declared capacities, availability windows, precedences, skills, compatibility zones and budget coordinates remain valid."); if (solve == null) d.Unknowns.Add("No matching certified grand solve bundle is attached."); if (stress == null) d.Unknowns.Add("No matching scenario-stress artifact is attached."); if (trade == null) d.Unknowns.Add("No matching Pareto trade space is attached."); if (baseline == null) d.Unknowns.Add("No immutable matching model baseline is attached."); if (capsule == null) d.Unknowns.Add("No preregistered optimization capsule is attached."); d.Unknowns.Add("External feasibility, data freshness, omitted constraints and implementation effects require independent review."); d.Dissent.Add("Absence of recorded dissent is not agreement and cannot authorize execution."); Store.Dossiers.Insert(0, d); Save(ctx); AppendLedger(ctx, "DOSSIER_CREATED", d.Id, d.Title, d.ModelFingerprint, ""); OpenRows(owner, "DECISION DOSSIER", d, d.AuthorityBoundary); }
        private static void OpenDossiers(Window owner, DeepSystemsContext ctx) { Load(ctx); OpenRows(owner, "DECISION DOSSIER VAULT", Store.Dossiers.ToArray(), "Recommendations remain attached to exact fingerprints, feasibility conditions, alternatives, unknowns and dissent"); }
        private static void ForkModel(Window owner, DeepSystemsContext ctx, WorldIndex index, OperationsResearchModel source) { string name = Prompt(owner, "FORK OPERATIONS MODEL", "Child model name", source.Name + " · branch"); if (String.IsNullOrWhiteSpace(name)) return; OperationsResearchModel child = Json.Deserialize<OperationsResearchModel>(Json.Serialize(source)); NormalizeModel(child); child.Id = Id("operations-model"); child.ParentModelId = source.Id; child.Name = name.Trim(); child.SourceKind = "MODEL_FORK"; child.SourceId = source.Id; child.SourceFingerprint = OperationsResearchKernel.Fingerprint(source); child.Status = "ACTIVE"; child.Revision = Math.Max(1, source.Revision) + 1; child.CreatedUtc = Now(); child.UpdatedUtc = child.CreatedUtc; Store.Models.Insert(0, child); Save(ctx); AppendLedger(ctx, "MODEL_FORKED", child.Id, "parent " + source.Id, OperationsResearchKernel.Fingerprint(child), ""); OpenModel(owner, ctx, index, child); }
        private static void OpenAudit(Window owner, DeepSystemsContext ctx) { Load(ctx); List<object> rows = new List<object>(); foreach (OperationsResearchModel model in Store.Models) { string fp = OperationsResearchKernel.Fingerprint(model); rows.Add((model.Name ?? model.Id) + "   ·   " + fp); rows.AddRange(OperationsResearchKernel.Audit(model).Cast<object>()); foreach (OrSolveRecord solve in Store.Solves.Where(x => Eq(x.ModelId, model.Id))) if (!Eq(solve.ModelFingerprint, fp)) rows.Add("HISTORY · solve " + solve.Id + " correctly remains bound to historical fingerprint " + Short(solve.ModelFingerprint, 20)); } foreach (OrModelBaseline b in Store.Baselines) if (!Eq(b.BaselineFingerprint, BaselineFingerprint(b))) rows.Add("BLOCKER · BASELINE_FINGERPRINT_MISMATCH · " + b.Id); rows.Add("LEDGER · " + VerifyLedger(ReadLedger(ctx, 32768))); OpenRows(owner, "FEASIBILITY & AUTHORITY AUDITOR", rows, "Structural, reference, provenance, historical and non-execution boundary audit"); }
        private static void OpenLedger(Window owner, DeepSystemsContext ctx) { List<OrLedgerRecord> rows = ReadLedger(ctx, 32768); OpenRows(owner, "OPERATIONS RESEARCH INTEGRITY LEDGER", new object[] { VerifyLedger(rows) }.Concat(rows.OrderByDescending(x => x.Sequence).Cast<object>()).ToArray(), "Append-only SHA-256 chain · " + LedgerPath(ctx)); }

        private static void Commit(DeepSystemsContext ctx, OperationsResearchModel model, string evt, string subject, string detail) { Touch(model); Save(ctx); AppendLedger(ctx, evt, subject, detail, OperationsResearchKernel.Fingerprint(model), ""); }
        private static void WithModel(Window owner, DeepSystemsContext ctx, Action<OperationsResearchModel> action) { OperationsResearchModel model = ChooseObject(owner, "SELECT OPERATIONS MODEL", "Choose an active planning world", Store.Models.Where(x => Active(x.Status)).OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).Cast<object>().ToList()) as OperationsResearchModel; if (model != null && action != null) action(model); }
        private static string CensusLine() { return Store.Models.Count + " models   ·   " + Store.Solves.Count + " solve bundles   ·   " + Store.StressRuns.Count + " stress runs   ·   " + Store.TradeSpaces.Count + " trade spaces   ·   " + Store.Capsules.Count + " preregistrations   ·   " + Store.Baselines.Count + " baselines   ·   " + Store.Dossiers.Count + " dossiers"; }

        private static void Load(DeepSystemsContext ctx) { lock (Gate) { if (Store != null && Eq(LoadedRoot, ctx.StateRoot)) return; LoadedRoot = ctx.StateRoot; Store = null; string path = StorePath(ctx); if (File.Exists(path)) try { Store = Json.Deserialize<OperationsResearchStore>(File.ReadAllText(path, Encoding.UTF8)); } catch { PreserveCorrupt(path); } if (Store == null && File.Exists(path + ".previous")) try { Store = Json.Deserialize<OperationsResearchStore>(File.ReadAllText(path + ".previous", Encoding.UTF8)); } catch { } if (Store == null) Store = new OperationsResearchStore(); NormalizeStore(); } }
        private static void NormalizeStore() { if (Store == null) Store = new OperationsResearchStore(); Store.Schema = 1; Store.Models = (Store.Models ?? new List<OperationsResearchModel>()).Where(x => x != null).ToList(); Store.Solves = (Store.Solves ?? new List<OrSolveRecord>()).Where(x => x != null).ToList(); Store.StressRuns = (Store.StressRuns ?? new List<OrStressRecord>()).Where(x => x != null).ToList(); Store.TradeSpaces = (Store.TradeSpaces ?? new List<OrTradeRecord>()).Where(x => x != null).ToList(); Store.Capsules = (Store.Capsules ?? new List<OrOptimizationCapsule>()).Where(x => x != null).ToList(); Store.Baselines = (Store.Baselines ?? new List<OrModelBaseline>()).Where(x => x != null).ToList(); Store.Dossiers = (Store.Dossiers ?? new List<OrDecisionDossier>()).Where(x => x != null).ToList(); foreach (OperationsResearchModel m in Store.Models) NormalizeModel(m); foreach (OrSolveRecord x in Store.Solves) x.Notes = x.Notes ?? new List<string>(); foreach (OrOptimizationCapsule x in Store.Capsules) { x.FrozenParameters = new Dictionary<string, double>(x.FrozenParameters ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase); x.Assumptions = x.Assumptions ?? new List<string>(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (OrDecisionDossier x in Store.Dossiers) { x.FeasibilityConditions = x.FeasibilityConditions ?? new List<string>(); x.Alternatives = x.Alternatives ?? new List<string>(); x.Unknowns = x.Unknowns ?? new List<string>(); x.Dissent = x.Dissent ?? new List<string>(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } }
        private static void NormalizeModel(OperationsResearchModel m) { if (m == null) return; m.Parameters = new Dictionary<string, double>(m.Parameters ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase); SeedParametersIfMissing(m); m.Locations = (m.Locations ?? new List<OrLocation>()).Where(x => x != null).Take(MaxNodes).ToList(); m.Arcs = (m.Arcs ?? new List<OrArc>()).Where(x => x != null).Take(MaxArcs).ToList(); m.Shipments = (m.Shipments ?? new List<OrShipment>()).Where(x => x != null).Take(MaxItems).ToList(); m.Vehicles = (m.Vehicles ?? new List<OrVehicle>()).Where(x => x != null).Take(MaxItems).ToList(); m.Tasks = (m.Tasks ?? new List<OrTask>()).Where(x => x != null).Take(MaxItems).ToList(); m.Resources = (m.Resources ?? new List<OrResourcePool>()).Where(x => x != null).Take(MaxItems).ToList(); m.Workers = (m.Workers ?? new List<OrWorker>()).Where(x => x != null).Take(MaxItems).ToList(); m.ShiftRequirements = (m.ShiftRequirements ?? new List<OrShiftRequirement>()).Where(x => x != null).Take(MaxItems).ToList(); m.Facilities = (m.Facilities ?? new List<OrFacilityCandidate>()).Where(x => x != null).Take(MaxItems).ToList(); m.Inventory = (m.Inventory ?? new List<OrInventoryItem>()).Where(x => x != null).Take(MaxItems).ToList(); m.WarehouseSlots = (m.WarehouseSlots ?? new List<OrWarehouseSlot>()).Where(x => x != null).Take(MaxItems).ToList(); m.Portfolio = (m.Portfolio ?? new List<OrPortfolioItem>()).Where(x => x != null).Take(MaxItems).ToList(); m.Scenarios = (m.Scenarios ?? new List<OrScenario>()).Where(x => x != null).Take(MaxItems).ToList(); m.Assumptions = m.Assumptions ?? new List<string>(); m.EvidenceNodeIds = (m.EvidenceNodeIds ?? new List<string>()).Take(MaxEvidence).ToList(); foreach (OrLocation x in m.Locations) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (OrArc x in m.Arcs) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (OrShipment x in m.Shipments) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (OrVehicle x in m.Vehicles) { x.Skills = x.Skills ?? new List<string>(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (OrTask x in m.Tasks) { x.PredecessorIds = x.PredecessorIds ?? new List<string>(); x.RequiredSkills = x.RequiredSkills ?? new List<string>(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (OrResourcePool x in m.Resources) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (OrWorker x in m.Workers) { x.Skills = x.Skills ?? new List<string>(); x.EligibleShiftIds = x.EligibleShiftIds ?? new List<string>(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (OrFacilityCandidate x in m.Facilities) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (OrInventoryItem x in m.Inventory) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (OrPortfolioItem x in m.Portfolio) { x.RequiredItemIds = x.RequiredItemIds ?? new List<string>(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (OrScenario x in m.Scenarios) x.Assumptions = x.Assumptions ?? new List<string>(); }
        private static void TrimStore() { NormalizeStore(); Store.Models = Store.Models.Take(MaxModels).ToList(); Store.Solves = Store.Solves.Take(MaxArtifacts).ToList(); Store.StressRuns = Store.StressRuns.Take(MaxArtifacts).ToList(); Store.TradeSpaces = Store.TradeSpaces.Take(MaxArtifacts).ToList(); Store.Capsules = Store.Capsules.Take(MaxArtifacts).ToList(); Store.Baselines = Store.Baselines.Take(MaxArtifacts).ToList(); Store.Dossiers = Store.Dossiers.Take(MaxArtifacts).ToList(); }
        private static void Save(DeepSystemsContext ctx) { lock (Gate) { TrimStore(); Store.Revision = Math.Max(0, Store.Revision) + 1; Store.UpdatedUtc = Now(); Store.LastCommitId = Id("operations-commit"); string path = StorePath(ctx); Directory.CreateDirectory(Path.GetDirectoryName(path)); AtomicWrite(path, Json.Serialize(Store)); } }
        private static void AtomicWrite(string path, string text) { string temp = path + ".tmp." + Guid.NewGuid().ToString("N"); File.WriteAllText(temp, text ?? "", new UTF8Encoding(false)); if (File.Exists(path)) { string previous = path + ".previous"; try { File.Replace(temp, path, previous, true); return; } catch { try { File.Copy(path, previous, true); } catch { } } } if (File.Exists(path)) File.Delete(path); File.Move(temp, path); }
        private static void PreserveCorrupt(string path) { try { if (!File.Exists(path)) return; byte[] bytes = File.ReadAllBytes(path); string destination = path + ".corrupt." + HashBytes(bytes).Substring(0, 16) + ".json"; if (!File.Exists(destination)) File.Copy(path, destination); } catch { } }
        private static string StorePath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-operations-research-empire.json"); }
        private static string LedgerPath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-operations-research-empire-ledger.jsonl"); }
        private static void AppendLedger(DeepSystemsContext ctx, string evt, string subject, string detail, string fingerprint, string certificate) { lock (Gate) try { Directory.CreateDirectory(ctx.StateRoot); List<OrLedgerRecord> prior = ReadLedger(ctx, 32768); OrLedgerRecord last = prior.OrderByDescending(x => x.Sequence).FirstOrDefault(); OrLedgerRecord r = new OrLedgerRecord { Schema = 1, Sequence = last == null ? 1 : last.Sequence + 1, Utc = Now(), Event = Short(evt, 120), Subject = Short(subject, 512), Detail = Short(detail, MaxLongText), CorrelationId = Store == null ? "" : Store.LastCommitId, ModelFingerprint = Short(fingerprint, 128), CertificateHash = Short(certificate, 128), PrevHash = last == null ? new string('0', 64) : last.EntryHash }; r.EntryHash = LedgerHash(r); byte[] bytes = Encoding.UTF8.GetBytes(Json.Serialize(r) + Environment.NewLine); using (FileStream stream = new FileStream(LedgerPath(ctx), FileMode.Append, FileAccess.Write, FileShare.Read, 4096, FileOptions.WriteThrough)) { stream.Write(bytes, 0, bytes.Length); stream.Flush(); } } catch { } }
        private static List<OrLedgerRecord> ReadLedger(DeepSystemsContext ctx, int cap) { List<OrLedgerRecord> rows = new List<OrLedgerRecord>(); if (!File.Exists(LedgerPath(ctx))) return rows; try { foreach (string line in TakeLast(File.ReadLines(LedgerPath(ctx)).Where(x => !String.IsNullOrWhiteSpace(x)), cap)) try { OrLedgerRecord row = Json.Deserialize<OrLedgerRecord>(line); if (row != null) rows.Add(row); } catch { } } catch { } return rows; }
        private static string VerifyLedger(List<OrLedgerRecord> rows) { if (rows == null || rows.Count == 0) return "EMPTY LEDGER"; rows = rows.OrderBy(x => x.Sequence).ToList(); long expected = rows[0].Sequence; string prior = expected == 1 ? new string('0', 64) : rows[0].PrevHash; foreach (OrLedgerRecord row in rows) { if (row.Sequence != expected) return "CHAIN GAP @ " + expected; if (!Eq(row.PrevHash, prior)) return "PREV HASH MISMATCH @ " + row.Sequence; if (!Eq(row.EntryHash, LedgerHash(row))) return "ENTRY HASH MISMATCH @ " + row.Sequence; expected++; prior = row.EntryHash; } return "CHAIN VERIFIED · " + rows.Count.ToString(CultureInfo.InvariantCulture) + " RECORDS"; }
        private static string LedgerHash(OrLedgerRecord r) { return HashText(r.Schema + "|" + r.Sequence + "|" + (r.Utc ?? "") + "|" + (r.Event ?? "") + "|" + (r.Subject ?? "") + "|" + (r.Detail ?? "") + "|" + (r.CorrelationId ?? "") + "|" + (r.ModelFingerprint ?? "") + "|" + (r.CertificateHash ?? "") + "|" + (r.PrevHash ?? "")); }

        private static void Touch(OperationsResearchModel m) { m.Revision = Math.Max(1, m.Revision) + 1; m.UpdatedUtc = Now(); }
        private static bool Active(string status) { return !Eq(status, "ARCHIVED") && !Eq(status, "DISABLED") && !Eq(status, "RETIRED") && !Eq(status, "REJECTED"); }
        private static bool Eq(string a, string b) { return String.Equals(a ?? "", b ?? "", StringComparison.OrdinalIgnoreCase); }
        private static double Number(string raw, double fallback) { double value; return Double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out value) && !Double.IsNaN(value) && !Double.IsInfinity(value) ? value : fallback; }
        private static int BoundedCapacity(double value) { if (Double.IsNaN(value) || Double.IsInfinity(value)) return 1; return (int)Math.Max(1, Math.Min(4096, Math.Ceiling(value))); }
        private static int Integer(string raw, int fallback, int minimum, int maximum) { int value; if (!Int32.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out value)) value = fallback; return Math.Max(minimum, Math.Min(maximum, value)); }
        private static double Clamp(double value, double minimum, double maximum) { return Math.Max(minimum, Math.Min(maximum, value)); }
        private static Dictionary<string, double> Pairs(string raw) { Dictionary<string, double> result = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); foreach (string line in (raw ?? "").Split(new[] { '\r', '\n', ';' }, StringSplitOptions.RemoveEmptyEntries)) { int at = line.IndexOf('='); if (at > 0) { string key = SafeKey(line.Substring(0, at).Trim()); if (!String.IsNullOrWhiteSpace(key)) result[key] = Number(line.Substring(at + 1).Trim(), 0); } } return result; }
        private static List<string> Tokens(string raw) { return (raw ?? "").Split(new[] { ',', ';', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).Where(x => x.Length > 0).Distinct(StringComparer.OrdinalIgnoreCase).ToList(); }
        private static string SafeKey(string value) { StringBuilder s = new StringBuilder(); foreach (char c in (value ?? "").ToLowerInvariant()) if (Char.IsLetterOrDigit(c) || c == '_') s.Append(c); else if (s.Length > 0 && s[s.Length - 1] != '_') s.Append('_'); return s.ToString().Trim('_'); }
        private static string Short(string value, int cap) { value = value ?? ""; cap = Math.Max(1, cap); return value.Length <= cap ? value : value.Substring(0, cap - 1) + "…"; }
        private static string HashText(string value) { return HashBytes(Encoding.UTF8.GetBytes(value ?? "")); }
        private static string HashBytes(byte[] value) { using (SHA256 hash = SHA256.Create()) return BitConverter.ToString(hash.ComputeHash(value ?? new byte[0])).Replace("-", "").ToLowerInvariant(); }
        private static string Id(string prefix) { return prefix + "-" + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8); }
        private static string Now() { return DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); }
        private static IEnumerable<TValue> TakeLast<TValue>(IEnumerable<TValue> source, int count) { Queue<TValue> q = new Queue<TValue>(); foreach (TValue item in source ?? Enumerable.Empty<TValue>()) { q.Enqueue(item); if (q.Count > count) q.Dequeue(); } foreach (TValue item in q) yield return item; }

        private static Window W(Window owner, string title, double width, double height) { return new Window { Title = title, Width = width, Height = height, MinWidth = Math.Min(width, 820), MinHeight = Math.Min(height, 560), Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = owner, FontFamily = new FontFamily("Segoe UI") }; }
        private static DockPanel Shell(string title, string subtitle) { DockPanel root = new DockPanel { Margin = new Thickness(16) }; StackPanel head = new StackPanel { Margin = new Thickness(0, 0, 0, 10) }; head.Children.Add(T(title, 24, Text, FontWeights.Bold)); head.Children.Add(T(subtitle, 12, Muted, FontWeights.Normal)); DockPanel.SetDock(head, Dock.Top); root.Children.Add(head); return root; }
        private static TextBlock T(string value, double size, Brush foreground, FontWeight weight) { return new TextBlock { Text = value ?? "", FontSize = size, Foreground = foreground, FontWeight = weight, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 2) }; }
        private static Button Btn(string label, RoutedEventHandler click) { Button button = new Button { Content = label, Margin = new Thickness(0, 0, 8, 8), Padding = new Thickness(12, 7, 12, 7), Background = Raised, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), MinWidth = 112 }; if (click != null) button.Click += click; return button; }
        private static ListBox List() { return new ListBox { Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), Margin = new Thickness(0, 6, 6, 0), Padding = new Thickness(5), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; }
        private static void Portal(Panel parent, string badge, string title, string description, Action open) { Button button = new Button { Width = 360, Height = 120, Margin = new Thickness(0, 0, 10, 10), Padding = new Thickness(12), Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), HorizontalContentAlignment = HorizontalAlignment.Stretch }; StackPanel content = new StackPanel(); content.Children.Add(T(badge + "   " + title, 14, Accent, FontWeights.Bold)); content.Children.Add(T(description, 11.5, Muted, FontWeights.Normal)); button.Content = content; button.Click += delegate { if (open != null) open(); }; parent.Children.Add(button); }
        private static Brush B(string hex) { return new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex)); }
        private static string Prompt(Window owner, string title, string label, string initial) { Window w = W(owner, "YOMI · " + title, 680, 290); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxShortText, Margin = new Thickness(0, 8, 0, 10), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(8) }; DockPanel.SetDock(editor, Dock.Top); root.Children.Add(editor); WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right }; string result = null; buttons.Children.Add(Btn("OK", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); root.Children.Add(buttons); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static string PromptLarge(Window owner, string title, string label, string initial) { Window w = W(owner, "YOMI · " + title, 800, 560); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxLongText, AcceptsReturn = true, AcceptsTab = true, TextWrapping = TextWrapping.Wrap, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Margin = new Thickness(0, 8, 0, 0), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(10), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; string result = null; buttons.Children.Add(Btn("SAVE", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(editor); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static object ChooseObject(Window owner, string title, string label, IList<object> choices) { Window w = W(owner, "YOMI · " + title, 720, 500); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); ListBox list = List(); list.ItemsSource = choices ?? new List<object>(); if (list.Items.Count > 0) list.SelectedIndex = 0; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; object result = null; buttons.Children.Add(Btn("SELECT", delegate { result = list.SelectedItem; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); list.MouseDoubleClick += delegate { result = list.SelectedItem; if (result != null) w.DialogResult = true; }; DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(list); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static void OpenRows(Window owner, string title, object value, string subtitle) { IEnumerable<object> rows = value as IEnumerable<object>; OpenRows(owner, title, rows == null ? new object[] { value } : rows.ToArray(), subtitle); }
        private static void OpenRows(Window owner, string title, IList<object> rows, string subtitle) { Window w = W(owner, "YOMI · " + title, 1240, 830); DockPanel root = Shell(title, subtitle); ListBox list = List(); list.ItemsSource = rows ?? new List<object>(); root.Children.Add(list); w.Content = root; w.Show(); }
    }
}
